# Kadane's: maximum sum of a contiguous subarray
arr = [-2, 1, -3, 4, -1, 2, 1, -5, 4]

current = arr[0]
best = arr[0]
for i in range(1, len(arr)):
    # if the running sum is negative, drop it and start fresh from this number
    if current < 0:
        current = arr[i]
    else:
        current = current + arr[i]
    if current > best:
        best = current
print(best)

# Merge Intervals: join the intervals that overlap
intervals = [[1, 3], [2, 6], [8, 10], [15, 18]]

intervals.sort()   # sort by start
merged = []
for start, end in intervals:
    if len(merged) > 0 and start <= merged[-1][1]:
        # overlaps with the last interval, so just stretch its end
        if end > merged[-1][1]:
            merged[-1][1] = end
    else:
        merged.append([start, end])
print(merged)

# Longest Substring Without Repeating Characters
s = "abcabcbb"

best = 0
for start in range(len(s)):
    seen = set()
    for j in range(start, len(s)):
        if s[j] in seen:
            break              # repeated letter, stop this substring
        seen.add(s[j])
    if len(seen) > best:
        best = len(seen)
print(best)

# Container With Most Water: two walls, find the biggest area
height = [1, 8, 6, 2, 5, 4, 8, 3, 7]

left = 0
right = len(height) - 1
best = 0
while left < right:
    width = right - left
    if height[left] < height[right]:
        h = height[left]
    else:
        h = height[right]
    area = width * h
    if area > best:
        best = area
    # move the shorter wall, because only that can give a bigger area
    if height[left] < height[right]:
        left = left + 1
    else:
        right = right - 1
print(best)

# Set Matrix Zeroes: if a cell is 0, make its whole row and column 0
matrix = [[1, 1, 1],
          [1, 0, 1],
          [1, 1, 1]]

rows = len(matrix)
cols = len(matrix[0])

zero_rows = set()
zero_cols = set()
for i in range(rows):
    for j in range(cols):
        if matrix[i][j] == 0:
            zero_rows.add(i)
            zero_cols.add(j)

for i in range(rows):
    for j in range(cols):
        if i in zero_rows or j in zero_cols:
            matrix[i][j] = 0
print(matrix)

# Merge Intervals: join the intervals that overlap
intervals = [[1, 3], [2, 6], [8, 10], [15, 18]]

intervals.sort()   # sort by start
merged = []
for start, end in intervals:
    if len(merged) > 0 and start <= merged[-1][1]:
        # overlaps with the last interval, so just stretch its end
        if end > merged[-1][1]:
            merged[-1][1] = end
    else:
        merged.append([start, end])
print(merged)

# Unique Paths II: robot moves only right/down, 1 = blocked cell
grid = [[0, 0, 0],
        [0, 1, 0],
        [0, 0, 0]]

rows = len(grid)
cols = len(grid[0])

# dp[i][j] = number of ways to reach cell (i, j)
dp = [[0] * cols for _ in range(rows)]
for i in range(rows):
    for j in range(cols):
        if grid[i][j] == 1:
            dp[i][j] = 0                  # blocked, no way to stand here
        elif i == 0 and j == 0:
            dp[i][j] = 1                  # start
        else:
            ways = 0
            if i > 0:
                ways = ways + dp[i - 1][j]    # coming from above
            if j > 0:
                ways = ways + dp[i][j - 1]    # coming from left
            dp[i][j] = ways
print(dp[rows - 1][cols - 1])

# Jump Game II: minimum jumps to reach the last index
nums = [2, 3, 1, 1, 4]

n = len(nums)
dp = [999999] * n       # dp[i] = minimum jumps needed to reach index i
dp[0] = 0
for i in range(n):
    for step in range(1, nums[i] + 1):
        if i + step < n:
            if dp[i] + 1 < dp[i + step]:
                dp[i + step] = dp[i] + 1
print(dp[n - 1])

