# Cycle in linked list (Floyd: slow moves 1 step, fast moves 2 steps)
# Input: line 1 = node values
#        line 2 = index where the last node points back (-1 if no cycle)
# Example: 1 2 3 4 / 1  ->  Cycle Detected
class Node:
    def __init__(self, val):
        self.val = val
        self.next = None

values = list(map(int, input().split()))
pos = int(input())

nodes = []
for v in values:
    nodes.append(Node(v))
for i in range(len(nodes) - 1):
    nodes[i].next = nodes[i + 1]
if pos != -1:
    nodes[-1].next = nodes[pos]      # make the cycle

slow = nodes[0]
fast = nodes[0]
found = False
while fast is not None and fast.next is not None:
    slow = slow.next
    fast = fast.next.next
    if slow == fast:
        found = True
        break

if found:
    print("Cycle Detected")
else:
    print("No Cycle")

