# qty 2 -> +3, qty 1 -> +2, qty 0 -> -2, not present -> -6
import sys
data = sys.stdin.read().split()

n = int(data[0])
stock = {}
pos = 1
for i in range(n):
    stock[data[pos]] = int(data[pos + 1])
    pos = pos + 2

q = int(data[pos])
queries = data[pos + 1:pos + 1 + q]

score = 0
for item in queries:
    if item not in stock:
        score = score - 6
    elif stock[item] == 2:
        score = score + 3
    elif stock[item] == 1:
        score = score + 2
    elif stock[item] == 0:
        score = score - 2
print(score)

